package slice;
import battle.*;
import band.*;
import game.GameSession;
import judgment.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SliceCombatTest {
    static class FixedRandom extends Random { int calls; @Override public double nextDouble(){calls++;return .3;} }
    static SliceBattle battle(GameSession s,Random rng){BattleEntity e=ContentBandTest.actor("enemy","Bass");e.maxHp=e.currentHp=500;e.affinities.put("modal","weak");return new SliceBattle(s,"test",new ArrayList<>(Arrays.asList(e)),rng);}
    static BandComposition.Assignment recipe(SliceBattle b,String id){return b.arrangements().stream().filter(a->a.recipe.id.equals(id)).findFirst().orElseThrow();}
    @Test void blueNoteActuallyExecutesAndDiscovers(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=battle(s,new FixedRandom());BattleResult r=b.arrange(recipe(b,"blue_note"),b.enemies.get(0),null,null);assertTrue(r.accepted);assertEquals(3,b.turns.iconCount());assertEquals(2,r.facts.stream().filter(f->f.type==BattleResult.Type.HIT).count());assertTrue(s.discoveries.contains("blue_note"));assertEquals(6,b.groove.current().score);assertEquals(1,b.groove.completedArrangements());assertTrue(s.active.get(1).arrangementCommitted);assertSame(s.active.get(1),b.actor());}
    @Test void invalidArrangementDoesNotChargeOrRoll(){GameSession s=new GameSession(ContentBandTest.catalog());FixedRandom rng=new FixedRandom();SliceBattle b=battle(s,rng);s.active.get(1).currentMp=0;int mp=s.active.get(0).currentMp;assertFalse(b.arrange(recipe(b,"blue_note"),b.enemies.get(0),null,null).accepted);assertEquals(mp,s.active.get(0).currentMp);assertEquals(4,b.turns.iconCount());assertEquals(0,rng.calls);}
    @Test void repelStopsSecondComponentAndClearsIcons(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=battle(s,new FixedRandom());b.enemies.get(0).affinities.put("modal","repel");BattleResult r=b.arrange(recipe(b,"blue_note"),b.enemies.get(0),null,null);assertEquals(0,b.turns.iconCount());assertEquals(1,r.facts.stream().filter(f->f.type==BattleResult.Type.MOVE).count());assertFalse(s.discoveries.contains("blue_note"));}
    @Test void protectionCompletesOnEnemyHitNotOnReadying(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=battle(s,new FixedRandom());b.defend();b.defend();BattleResult ready=b.arrange(recipe(b,"locked_in"),null,null,null);assertTrue(ready.accepted);assertFalse(s.discoveries.contains("locked_in"));b.advancePhase();BattleResult hit=b.enemyStep();assertTrue(hit.facts.stream().anyMatch(f->f.type==BattleResult.Type.PROTECTED));assertTrue(s.discoveries.contains("locked_in"));assertEquals(1,b.groove.completedArrangements());}
    @Test void fullChorusHasSingleAggregateAndSuppressesEnemyBand(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=battle(s,new FixedRandom());BattleResult r=b.arrange(recipe(b,"full_chorus"),b.enemies.get(0),null,null);assertTrue(r.accepted);assertEquals(1,b.turns.iconCount());assertFalse(r.facts.stream().anyMatch(f->f.type==BattleResult.Type.ENEMY_BAND_DISRUPTED));}
    @Test void walkingSoloSchedulesSaxWithoutGivingFreeCommand(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=battle(s,new FixedRandom());assertTrue(b.arrange(recipe(b,"walking_solo"),b.enemies.get(0),null,"riff").accepted);assertSame(s.active.get(1),b.actor());int icons=b.turns.iconCount();b.move("riff",b.enemies.get(0));assertEquals(icons-1,b.turns.iconCount());}
    @Test void judgmentHasTwoGatesAndExactlyThreeIdempotentAttempts(){GameSession s=new GameSession(ContentBandTest.catalog());JudgmentEvaluator evaluator=new JudgmentEvaluator();assertFalse(evaluator.evaluate(s.desire,1,1,1,0).passed);assertFalse(evaluator.evaluate(s.desire,0,0,0,100).passed);assertTrue(evaluator.evaluate(s.desire,1,1,1,3).passed);JudgmentEvaluator.Evaluation fail=evaluator.evaluate(s.desire,0,0,0,0);s.judgment.commit("a",fail);s.judgment.commit("a",fail);assertEquals(1,s.judgment.attemptsUsed());s.judgment.commit("b",fail);s.judgment.commit("c",fail);assertTrue(s.judgment.gameOver);assertEquals("judgment_third_failure",s.judgment.cutsceneHook());assertThrows(IllegalStateException.class,()->s.judgment.commit("d",fail));}
    @Test void fieldProgressionKeepsIdentitiesAndUnlocksInstrument(){GameSession s=new GameSession(ContentBandTest.catalog());assertThrows(IllegalArgumentException.class,()->s.equip("trumpet"));s.resolvedEncounters.add("1");s.acquireReward();s.acquireReward();assertEquals(1,s.reserve.size());s.equip("trumpet");assertEquals("blast",s.active.get(0).basicAttack);BattleEntity original=s.active.get(3);s.fieldSwap(3,0);assertSame(original,s.reserve.get(0));assertEquals("ally:jjj",s.active.get(3).instanceId);}
}
